<template>
  <el-card>
    <div style="display: flex;justify-content: space-between;">
      <el-form style="width: 30%;" :model="ruleForm" :rules="rules" ref="ruleForm" label-width="100px" class="demo-ruleForm">
        <el-form-item label="服务器端口" prop="serverPort">
          <el-input v-model="ruleForm.serverPort"></el-input>
        </el-form-item>
        <el-form-item label="发送延迟" prop="sendingInterval">
          <el-input v-model="ruleForm.sendingInterval"></el-input>
        </el-form-item>
        <el-form-item label="命令数量" prop="sendingCount">
          <el-input v-model="ruleForm.sendingCount"></el-input>
        </el-form-item>
        <el-form-item label="kafka上传" prop="topic">
          <el-input v-model="ruleForm.topic"></el-input>
        </el-form-item>
        <el-collapse v-model="activeNames" style="margin: 20px 0 20px 30px;" class="aqzCollapse">
          <el-collapse-item title="kafka客户端" name="1">
            <el-form-item label="服务器IP" prop="kafkaIp">
              <el-input v-model="ruleForm.kafkaIp"></el-input>
            </el-form-item>
            <el-form-item label="服务器端口" prop="kafkaPort">
              <el-input v-model="ruleForm.kafkaPort"></el-input>
            </el-form-item>
            <el-form-item label="本地主题" prop="kafkaTopics">
              <el-input v-model="ruleForm.kafkaTopics"></el-input>
            </el-form-item>
          </el-collapse-item>
        </el-collapse>
        <el-form-item>
          <el-button type="primary" @click="submitForm('ruleForm')">更新</el-button>
          <el-button @click="restartFun">重启服务</el-button>
        </el-form-item>
      </el-form>
      <div style="width: 35%;" class="tabPaneLabelClass">
        <el-button style="width: 110px;margin-left: 20px;" size="mini" @click="addTab(0)" icon="el-icon-plus"></el-button>
        <el-tabs v-model="editableTabsValue" tab-position="left" :closable="controls.length > 1" @tab-remove="removeTab">
          <el-tab-pane v-for="item in controls" :key="item.id" :label="item.name" :name="item.id">
            <el-descriptions class="margin-top" :column="1" border size="mini">
              <el-descriptions-item label="名称"><el-input size="mini" v-model="item.name" @input="controlName(item.name, item.id)"></el-input></el-descriptions-item>
              <el-descriptions-item label="IP"><el-input size="mini" v-model="item.ip"></el-input></el-descriptions-item>
              <el-descriptions-item label="端口"><el-input size="mini" v-model="item.port"></el-input></el-descriptions-item>
              <el-descriptions-item label="全息编号"><el-input type="textarea" :autosize="{ minRows: 2, maxRows: 4 }" size="mini" v-model="item.quanXiId"></el-input></el-descriptions-item>
              <el-descriptions-item label="灯编号"><el-input size="mini" v-model="item.lightId"></el-input></el-descriptions-item>
              <el-descriptions-item label="连接方式">
                <el-select v-model="item.connectType" placeholder="请选择" size="small" style="width: 100%;">
                  <el-option label="tcp" value="tcp"></el-option>
                  <el-option label="udp" value="udp"></el-option>
                </el-select>
              </el-descriptions-item>
            </el-descriptions>
          </el-tab-pane>
        </el-tabs>
      </div>
      <div style="width: 34%;">
      </div>
    </div>
  </el-card>
</template>
<script>
import { getCfgInfo, restart, setCfgInfo } from '@/api/jingShiDeng'
import { logout } from '@/api/login'
export default {
  name: 'jingShiDeng',
  data() {
    let ipv4Reg = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/
    let portReg = /^([1-9]\d{0,3}|[1-5]\d{4}|6[0-4]\d{3}|65[0-4]\d{2}|655[0-2]\d|6553[0-5])$/
    return {
      activeNames: '1',
      ruleForm: {
        serverPort: '2333',
        sendingInterval: '1000',
        sendingCount: '10',
        topic: 'deviceState',
        kafkaIp: '58.240.67.138',
        kafkaPort: '18543',
        kafkaTopics: 'nh_deviceState,nh_deviceState'
      },
      rules: {
        serverPort: [ { required: true, message: '请填写', trigger: 'blur' }, { pattern: portReg, message: '请输入有效的端口', trigger: 'blur' } ],
        sendingInterval: [ { required: true, message: '请填写', trigger: 'blur' } ],
        sendingCount: [ { required: true, message: '请填写', trigger: 'blur' } ],
        topic: [ { required: true, message: '请填写', trigger: 'blur' } ],
        kafkaIp: [ { required: true, message: '请填写', trigger: 'blur' }, { pattern: ipv4Reg, message: '请输入有效的IP', trigger: 'blur' } ],
        kafkaPort: [ { required: true, message: '请填写', trigger: 'blur' }, { pattern: portReg, message: '请输入有效的端口', trigger: 'blur' } ],
        kafkaTopics: [ { required: true, message: '请填写', trigger: 'blur' } ],
      },
      cfgInfo: '',
      controls: [{
        'id': '0',
        'ip':"192.168.1.101",
        'port': "8889",
        'quanXiId': "QuanXiId1,QuanXiId2,QuanXiId3,QuanXiId4",
        'name': "警示灯网络控制器",
        'lightId': "1-2;3-4",
        'connectType': "tcp"
      }],
      editableTabsValue: '0',
      controlData: []
    };
  },
  methods: {
    getCfgFun() {
      getCfgInfo().then((res) => {
        this.ruleForm = Object.assign(this.ruleForm, res)
        res.controllers.forEach((item, index) => {
          item.id = index + ''
        })
        this.controls = res.controllers
        this.controlData = JSON.parse(JSON.stringify(this.controls))
        delete this.ruleForm.controllers
      })
    },
    addTab() {
      let obj = {
        'id': +new Date() + 'id',
        'ip':"192.168.1.101",
        'port': "8889",
        'quanXiId': "QuanXiId1,QuanXiId2,QuanXiId3,QuanXiId4",
        'name': "警示灯网络控制器" + this.controls.length,
        'lightId': "1-2;3-4",
        'connectType': "tcp"
      }
      this.controls.push(obj);
      this.controlData = JSON.parse(JSON.stringify(this.controls))
      this.editableTabsValue = obj.id;
    },
    removeTab(targetName) {
      this.controls = this.controls.filter(tab => tab.id !== targetName);
      if (this.controls[this.controls.length - 1]) {
        this.editableTabsValue = this.controls[this.controls.length - 1].id
      }
    },
    controlName(name, id) {
      let data1 = this.controlData.filter(tab => tab.id == id)[0]
      let data2 = this.controls.filter(tab => tab.id == id)[0]
      if (name.length <= 1) {
        data2.name = data1.name.substring(0,1);
      }
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.ruleForm.controllers = this.controls
          setCfgInfo(this.ruleForm).then(res => {
            if (res.code == 200) {
              this.$message({
                message: res.msg,
                type: 'success'
              });
            }
          })
        } else {
          return false;
        }
      });
    },
    restartFun() {
      restart().then(res => {
        if (res.code == '200'){
          this.$message({
            message: '警示灯重启中 即将退出...',
            type: 'success'
          });
          setTimeout(() => {
            logout().then(() => {
              this.$router.push('/login')
            })
          }, 2000)
        }
      })
    }
  },
  mounted() {
    this.getCfgFun()
  }
}
</script>
