<template>
  <el-card>
    <div style="display: flex;justify-content: space-between;">
      <el-form style="width: 500px;" :model="ruleForm" :rules="rules" ref="ruleForm" label-width="100px" class="demo-ruleForm">
        <el-form-item label="LED屏IP" prop="LEDIP">
          <el-input v-model="ruleForm.LEDIP"></el-input>
        </el-form-item>
        <el-form-item label="安全桩IP" prop="aqzIP">
          <el-input v-model="ruleForm.aqzIP"></el-input>
        </el-form-item>
        <el-collapse v-model="activeNames" style="margin: 20px 0 20px 30px;" class="aqzCollapse">
          <el-collapse-item title="屏幕文字" name="1">
            <el-form-item label="触发前" prop="after">
              <el-input v-model="ruleForm.after"></el-input>
            </el-form-item>
            <el-form-item label="触发后" prop="later">
              <el-input v-model="ruleForm.later"></el-input>
            </el-form-item>
            <el-form-item label="文字颜色" prop="color">
              <el-input v-model="ruleForm.color"></el-input>
            </el-form-item>
          </el-collapse-item>
        </el-collapse>
        <el-form-item label="红绿灯颜色" prop="trafficLight">
          <el-select v-model="ruleForm.trafficLight" placeholder="请选择">
            <el-option label="红" value="红"></el-option>
            <el-option label="绿" value="绿"></el-option>
            <el-option label="黄" value="黄"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="submitForm('ruleForm')">更新</el-button>
          <el-button @click="fetchForm('ruleForm')">重置</el-button>
        </el-form-item>
      </el-form>
      <div style="width: 800px;">
        <el-button type="primary" @click="getData()">读取</el-button>
        <el-button type="primary" @click="restartFun()">重启安全桩</el-button>
        <el-card style="margin-top: 10px;">
          <div class="bg">
            <div class="shine" v-html="cfgInfo"></div>
          </div>
        </el-card>
      </div>
    </div>
  </el-card>
</template>
<script>
import { getCfgInfo, restart, updateCfgInfo } from '@/api/anQuanZhuang'
import { logout } from '@/api/login'
export default {
  name: 'anQuanZhuang',
  data() {
    let ipv4Reg = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?):(?:6553[0-5]|655[0-2][0-9]|65[0-4][0-9]{2}|6[0-4][0-9]{3}|[1-5][0-9]{4}|[1-9][0-9]{0,3}|0)$/
    return {
      activeNames: '1',
      ruleForm: {
        LEDIP: '192.168.0.55:8000',
        aqzIP: '192.168.0.55:8000',
        after: '安全行车',
        later: '文明驾驶',
        color: '红',
        trafficLight: '红'
      },
      rules: {
        LEDIP: [ { required: true, message: '请填写', trigger: 'blur' }, { pattern: ipv4Reg, message: '请输入有效的IP', trigger: 'blur' } ],
        aqzIP: [ { required: true, message: '请填写', trigger: 'blur' }, { pattern: ipv4Reg, message: '请输入有效的IP', trigger: 'blur' } ],
        after: [ { required: true, message: '请填写', trigger: 'blur' } ],
        later: [ { required: true, message: '请填写', trigger: 'blur' } ],
        color: [ { required: true, message: '请填写', trigger: 'blur' } ],
        trafficLight: [ { required: true, message: '请选择', trigger: 'blur' } ],
      },
      cfgInfo: ''
    };
  },
  methods: {
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          updateCfgInfo(this.ruleForm).then(res => {
            if (res.code == 200) {
              this.$message({
                message: res.msg,
                type: 'success'
              });
            }
          })
        } else {
          return false;
        }
      });
    },
    fetchForm(formName) {
      this.$refs[formName].resetFields();
    },
    getData() {
      getCfgInfo().then(res => {
        this.cfgInfo = JSON.stringify(res).replace('{', '').replace('}', '').replaceAll('"', '').replaceAll(',', '<br>')
      })
    },
    restartFun() {
      restart().then(res => {
        if (res == '200'){
          this.$message({
            message: '安全桩重启中 即将退出...',
            type: 'success'
          });
          setTimeout(() => {
            logout().then(() => {
              this.$router.push('/login')
            })
          }, 2000)
        }
      })
    }
  },
  mounted() {
    this.getData()
  }
}
</script>
