<template>
  <el-card>
    域名/IP:<el-input v-model="jingShiDengIP" style="width: 240px;margin-left: 10px" size="small" readonly/>
    <el-tabs v-model="activeName">
      <el-tab-pane label="广播模式" name="1">
        <el-form style="width: 40%;" label-position="left" :model="ruleForm" ref="ruleForm">
          <el-form-item label="控制器列表" prop="ControllerIpPort" label-width="115px">
            <el-select v-model="ruleForm.ControllerIpPort" placeholder="请选择" size="small" style="width: 332px;">
              <el-option v-for="(v, i) in controls" :key="i" :label="v.name" :value="v.ip + ':' + v.port"></el-option>
            </el-select>
            <el-button icon="el-icon-refresh" circle size="mini" style="margin-left: 10px;" @click="getCfgFun"></el-button>
          </el-form-item>
          <el-checkbox-group v-model="checkList">
            <el-checkbox label="Content">
              <el-form-item label="改变文字" prop="Content" label-width="90px">
                <el-input v-model="ruleForm.Content" size="small" style="width: 332px;"></el-input>
              </el-form-item>
            </el-checkbox>
            <el-checkbox label="Luminance">
              <el-form-item label="改变亮度" prop="Luminance" label-width="90px">
                <el-input-number v-model="ruleForm.Luminance" size="small" style="width: 332px;"></el-input-number>
              </el-form-item>
            </el-checkbox>
            <el-checkbox label="Flicker">
              <el-form-item label="改变闪烁" prop="Flicker" label-width="90px">
                <span style="color: #606266;">亮</span><el-input-number :min="0" :max="4" v-model="ruleForm.Flicker[0]" size="mini" style="width: 100px;margin-left: 10px;"></el-input-number><span style="color: #606266;margin-right: 10px;">(秒)</span>
                <span style="color: #606266;">灭</span><el-input-number :min="0" :max="2" v-model="ruleForm.Flicker[1]" size="mini" style="width: 100px;margin-left: 10px;"></el-input-number><span style="color: #606266;">(秒)</span>
              </el-form-item>
            </el-checkbox>
            <el-checkbox label="FontColor">
              <el-form-item label="改变颜色" prop="FontColor" label-width="90px">
                <el-select v-model="ruleForm.FontColor" placeholder="请选择" size="small" style="width: 332px;">
                  <el-option label="红" :value="1"></el-option>
                  <el-option label="绿" :value="2"></el-option>
                  <el-option label="蓝" :value="3"></el-option>
                  <el-option label="白" :value="4"></el-option>
                  <el-option label="黄" :value="5"></el-option>
                  <el-option label="青" :value="6"></el-option>
                  <el-option label="洋红" :value="7"></el-option>
                  <el-option label="黑" :value="8"></el-option>
                  <el-option label="橙" :value="9"></el-option>
                </el-select>
              </el-form-item>
            </el-checkbox>
            <el-checkbox label="PathTracking">
              <el-form-item label="改变轨迹模式" prop="PathTracking" label-width="90px">
                <el-select v-model="ruleForm.PathTracking" placeholder="请选择" size="small" style="width: 332px;">
                  <el-option label="关闭轨迹跟踪模式" :value="0"></el-option>
                  <el-option label="开启轨迹跟踪模式一" :value="1"></el-option>
                  <el-option label="开启轨迹跟踪模式二" :value="2"></el-option>
                </el-select>
              </el-form-item>
            </el-checkbox>
          </el-checkbox-group>
          <el-form-item>
            <div style="display: flex;">
              <el-button type="primary" @click="submitForm" style="margin-right: 70px;">发送命令</el-button>
              <el-form-item label="版本" prop="Version" label-width="40px">
                <el-select v-model="ruleForm.Version" placeholder="请选择" size="small" style="width: 100px;">
                  <el-option label="1" :value="1"></el-option>
                  <el-option label="2" :value="2"></el-option>
                </el-select>
              </el-form-item>
            </div>
          </el-form-item>
        </el-form>
      </el-tab-pane>
      <el-tab-pane label="多文字模式" name="2">
        <el-form style="width: 40%;" label-position="left" :model="multitextForm" ref="multitextForm">
          <el-form-item label="控制器列表" prop="ControllerIpPort" label-width="90px">
            <el-select v-model="multitextForm.ControllerIpPort" placeholder="请选择" size="small" style="width: 332px;">
              <el-option v-for="(v, i) in controls" :key="i" :label="v.name" :value="v.name"></el-option>
            </el-select>
            <el-button icon="el-icon-refresh" circle size="mini" style="margin-left: 10px;"></el-button>
          </el-form-item>
          <el-form-item label="改变文字" prop="Lights" label-width="90px">
            <el-input type="textarea" :autosize="{ minRows: 1, maxRows: 4 }" v-model="multitextForm.Lights" size="small" style="width: 332px;" maxlength="254"></el-input>
          </el-form-item>
          <el-form-item label="雾灯编号" prop="lightId" label-width="90px">
            <el-input v-model="lightId" size="small" style="width: 332px;"></el-input>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="submitMultitext" style="margin-right: 80px;">发送命令</el-button>
          </el-form-item>
        </el-form>
      </el-tab-pane>
    </el-tabs>
  </el-card>
</template>
<script>
import { getCfgInfo } from '@/api/jingShiDeng'
import { Broadcast, BroadcastNot } from '@/api/jingShiDengDB'
export default {
  name: 'jingShiDengDB',
  data() {
    return {
      activeName: '1',
      jingShiDengIP: 'http://127.0.0.1',
      ruleForm: {
        Content: '雨',
        ControllerIpPort: "",
        Flicker: [1, 1],
        FontColor: 1,
        Luminance: 30,
        PathTracking: 1,
        Version: 2
      },
      checkList: [],
      controls: [],
      multitextForm: {
        ControllerIpPort: "",
        Lights: '雨天路滑'
      },
      lightId: '1-4'
    };
  },
  methods: {
    getCfgFun() {
      getCfgInfo().then((res) => {
        this.controls = res.controllers
        this.ruleForm.ControllerIpPort = this.controls[0] ? this.controls[0].ip + ':' + this.controls[0].port : ''
        this.multitextForm.ControllerIpPort = this.ruleForm.ControllerIpPort
      })
    },
    submitForm() {
      if (this.checkList.length > 0) {
        let params = {
          ControllerIpPort: this.ruleForm.ControllerIpPort,
          Version: this.ruleForm.Version
        }
        this.checkList.forEach((item) => {
          if (item == 'Flicker') {
            let arr = []
            this.ruleForm[item].forEach(item => {
              arr.push(item * 1000)
            })
            params[item] = arr
          } else {
            params[item] = this.ruleForm[item]
          }
        })
        Broadcast(params).then(res => {
          if (res.code == 200) {
            this.$message({
              message: res.msg,
              type: 'success'
            });
          }
        })
      } else {
        this.$alert('请勾选需要修改的选项')
      }
    },
    expandRanges(rangeStr) {
      return rangeStr.split(',')
        .flatMap(range => {
          const [start, end = start] = range.split('-').map(Number);
          return Array.from({ length: end - start + 1 }, (_, i) => start + i);
        });
    },
    submitMultitext() {
      if (this.lightId) {
        let arr = this.lightId.split(';')
        let lightIds = []
        arr.forEach(item => {
          lightIds.push(...this.expandRanges(item))
        })
        let strs = this.multitextForm.Lights.split('')
        if (lightIds.length == strs.length) {
          let params = { Lights: [], ControllerIpPort: this.multitextForm.ControllerIpPort }
          strs.forEach((item, index) => {
            params.Lights.push({ Content: item, LightId: lightIds[index] })
          })
          BroadcastNot(params).then(res => {
            if (res.code == 200) {
              this.$message({
                message: res.msg,
                type: 'success'
              });
            }
          })
        } else {
          this.$alert('文字数量与id数量不符')
        }
      }
    },
  },
  mounted() {
    this.jingShiDengIP = this.jingShiDengIP + ':' + window.location.port
    this.getCfgFun()
  }
}
</script>
