import request from '@/utils/request'
export function Broadcast(params) {
  return request({
    url: '/jingShiDeng/Broadcast',
    method: 'post',
    data: params
  })
}
export function BroadcastNot(params) {
  return request({
    url: '/jingShiDeng/BroadcastNot',
    method: 'post',
    data: params
  })
}